"""The public sample cell, LAUNCHED (opt-in): ``examples/ur5e_suction`` generated by the TSA under
test into a temp workspace, built, brought up on mock and its application run -- the sample
README's steps 1-3, done by a test on a ROS domain of its own.

    generate the sample the README's way (from its directory, its paths relative), renamed to
      tsample_* so it never collides with a bundle the user built from the sample
      -> colcon build over the sourced workspace: 3 packages
      -> ``ros2 launch tsample_app bringup.launch.py mode:=mock rviz:=false``: move_group ready,
         the arm controller active, the trainit_mock adapter for /eef/main up
      -> ``ros2 launch tsample_app trainit_bt.launch.py use_sim_time:=false groot_monitor:=false``:
         the tree ends SUCCESS within TREE_TIMEOUT_S and its launch exits 0; its 8 moves run in
         the sequence's order, each validated WITH collision checking (the UR meshes, the tool,
         the table and the held box); the cup engages after pick and releases after place, the
         box attached and detached around them; move_group receives one MoveGroup and one
         ExecuteTrajectory goal per move and executes all of them; no log names a missing joint
         state, a failed plan or validation, a contact or a robot without geometry
      -> both launches end within 30 s of their SIGINT (the runner's by itself, when its tree
         ends) and leave no process; ROS domain 79 holds no node before and none after

OPT-IN: it builds and launches for a few minutes, so it runs only with ``TRAINIT_LAUNCH_TEST=1``
and a sourced workspace (ROS 2 Humble + the TrainIt workspace's install). It SKIPS, naming the
cause, with a trainit_motion_runtime or trainit_hardware_layer older than the generated
package.xml declares. Without ur_description and xacro (the static module's check: sudo apt
install ros-humble-ur-description), and on a machine that lacks what the generated bundle
declares (``launch_prereqs``, after generating and before the build), it SKIPS naming each
package and the fix -- and with TRAINIT_REQUIRE_GOLDEN=1 those two FAIL instead. Every launch
runs in its own session on ROS domain 79 (no other TrainIt test uses it), ROS_LOCALHOST_ONLY=1,
with TMPDIR and ROS_LOG_DIR inside the temp workspace, which may not lie inside a sourced
workspace (composite_launch). Test-time generation, removed at teardown: not a bundle for anyone
to ship (MANUAL TSA GENERATION CHECKPOINT). With ``TRAINIT_SAMPLE_LAUNCH_EVIDENCE=<dir>`` the
report and every launch log are copied to ``<dir>/ur5e_suction/`` first, and colcon's own logs
too when the build fails.
"""
import os
import re
import shlex
import shutil
import subprocess
import time
import xml.etree.ElementTree as ET
from pathlib import Path

import pytest

pytestmark = pytest.mark.skipif(os.environ.get('TRAINIT_LAUNCH_TEST') != '1',
                                reason='opt-in: set TRAINIT_LAUNCH_TEST=1 (builds and launches)')

EXAMPLE = Path(__file__).resolve().parents[1] / 'examples' / 'ur5e_suction'
PREFIX = 'tsample'
DOMAIN = 79
TREE_TIMEOUT_S = 180.0
EVIDENCE = 'TRAINIT_SAMPLE_LAUNCH_EVIDENCE'
SEQUENCE = ['home', 'pre_pick', 'pick', 'post_pick', 'pre_place', 'place', 'post_place', 'home']
SITE = '/eef/main/sites/main'
# The runner's semantic lines, in the order the tree must produce them.
EVENT = re.compile(r"\]: (added collision box '\w+'|MoveWaypoint '\w+'(?= \()"
                   r"|(?:Close|Open)Gripper \S+ \([^)]*\): [A-Z_]+"
                   r"|attached '\w+' to '\w+'|detached '\w+'|BT finished: \w+)")
EXPECTED = ["added collision box 'table'",
            *[f"MoveWaypoint '{w}'" for w in SEQUENCE[:3]],
            f'CloseGripper {SITE} (vacuum -> engage): SUCCESS', "attached 'box' to 'tcp'",
            *[f"MoveWaypoint '{w}'" for w in SEQUENCE[3:6]],
            f'OpenGripper {SITE} (vacuum -> release): SUCCESS', "detached 'box'",
            *[f"MoveWaypoint '{w}'" for w in SEQUENCE[6:]],
            'BT finished: SUCCESS']
# move_group's log, one line per goal (as test_m2_7_bundle_runner_launch.py counts them).
GOALS = (('MoveGroup goals', 'move_action_capability]: Received request'),
         ('ExecuteTrajectory goals',
          'execute_trajectory_action_capability]: Received goal request'),
         ('executions SUCCEEDED',
          'execute_trajectory_action_capability]: Execution completed: SUCCEEDED'))
# Never in either log.
NEVER = ('does not include the parent link', 'PLAN FAILED', 'VALIDATION FAILED',
         'Found a contact between', 'No geometry is associated to any robot links')
# Never in the runner's log: it starts after the controllers are active, so a joint state it
# misses is one nobody publishes (the pseudo-joint the sample does not have).
NEVER_IN_RUNNER = ('complete state of the robot is not yet known',)


def _cl():
    import composite_launch
    return composite_launch


def _floors(package_xml: Path) -> dict:
    """{package: (x, y, z)}: every version_gte exec_depend of a generated package.xml."""
    return {e.text.strip(): tuple(int(x) for x in e.get('version_gte').split('.'))
            for e in ET.parse(package_xml).getroot().iter('exec_depend')
            if e.get('version_gte')}


class SampleLaunch:
    """The bring-up, then the runner, on the bundle built in ws."""

    def __init__(self, ws: Path):
        CL = _cl()
        self.ws = CL._outside_the_underlay(ws)
        self.logs, self.tmp, self.ros_log = self.ws / 'logs', self.ws / 'tmp', self.ws / 'ros_log'
        for d in (self.logs, self.tmp, self.ros_log):
            d.mkdir(parents=True, exist_ok=True)
        self.env = dict(os.environ, ROS_DOMAIN_ID=str(DOMAIN), ROS_LOCALHOST_ONLY='1',
                        RCUTILS_COLORIZED_OUTPUT='0', ROS_LOG_DIR=str(self.ros_log),
                        TMPDIR=str(self.tmp))
        self.lines, self.guards, self.stops, self.ready = [], {}, {}, {}
        self.timed_out = None
        self.launch_params = 0

    def say(self, text: str) -> None:
        self.lines.append(text)
        print(text, flush=True)

    def report(self) -> str:
        return '\n'.join(self.lines) + '\n'

    def save(self, dest: Path) -> None:
        dest.mkdir(parents=True, exist_ok=True)
        (dest / 'report.txt').write_text(self.report())
        for log in sorted(self.logs.glob('*.log')):
            shutil.copy(log, dest / log.name)

    def _launch(self, what: str, log: Path) -> subprocess.Popen:
        CL = _cl()
        cmd = (CL._sourced(str(self.ws / 'install' / 'setup.bash')) +
               f' && exec ros2 launch {what} > {shlex.quote(str(log))} 2>&1')
        return subprocess.Popen(['bash', '-c', cmd], env=self.env, start_new_session=True)

    def _guard(self, tag: str) -> list:
        CL = _cl()
        probe = CL._Probe(DOMAIN, f'tsample_guard_{len(self.guards) + 1}', self.ros_log)
        try:
            time.sleep(CL.SETTLE_S)
            nodes = [f'{ns.rstrip("/")}/{n}' for ns, n in probe.nodes()]
        finally:
            probe.close()
        self.guards[tag] = nodes
        self.say(f'[guard] ROS domain {DOMAIN} {tag} the launches: {nodes or "no node"}')
        return nodes

    def run(self) -> 'SampleLaunch':
        CL = _cl()
        if self._guard('before'):
            raise RuntimeError(f'ROS domain {DOMAIN} is not empty: refusing to launch on it')
        up = bt = None
        bringup = self.logs / 'bringup.log'
        try:
            up = self._launch(f'{PREFIX}_app bringup.launch.py mode:=mock rviz:=false', bringup)
            self.ready = {
                'move_group ready': CL._wait_log(bringup, r'You can start planning now', 120),
                'arm controller active': CL._wait_log(
                    bringup, r'Configured and activated .*moveit_joint_controller', 60),
                'mock adapter up': CL._wait_log(
                    bringup, re.escape('trainit_mock adapter for /eef/main'), 60)}
            self.say(f'[bring-up] {self.ready}')
            if all(self.ready.values()):
                time.sleep(2.0)
                bt = self._launch(f'{PREFIX}_app trainit_bt.launch.py use_sim_time:=false '
                                  f'groot_monitor:=false', self.logs / 'runner.log')
                try:
                    bt.wait(timeout=TREE_TIMEOUT_S)
                    self.timed_out = False
                except subprocess.TimeoutExpired:
                    self.timed_out = True
        finally:
            if bt is not None:
                self.stops['runner'] = CL.CompositeLaunch._stop_outcome(bt)
            if up is not None:
                self.stops['bring-up'] = CL.CompositeLaunch._stop_outcome(up)
            self.launch_params = sum(1 for _ in self.tmp.glob('launch_params_*'))
            self._guard('after')
        self._read()
        return self

    def _read(self) -> None:
        CL = _cl()
        runner_log, bringup_log = self.logs / 'runner.log', self.logs / 'bringup.log'
        runner = runner_log.read_text(errors='replace') if runner_log.is_file() else ''
        bringup = bringup_log.read_text(errors='replace') if bringup_log.is_file() else ''
        parsed = CL.CompositeLaunch._parse(runner, self.timed_out is not False)
        self.finished, self.code, self.steps = parsed['finished'], parsed['code'], parsed['steps']
        self.events = EVENT.findall(runner)
        self.moves = re.findall(r"\]: MoveWaypoint '(\w+)' \(", runner)
        self.validated = runner.count('validation OK (collision_checked=1')
        move_group = [line for line in bringup.splitlines() if line.startswith('[move_group-')]
        self.goals = {what: sum(p in line for line in move_group) for what, p in GOALS}
        self.never = sorted({n for n in NEVER if n in runner or n in bringup}
                            | {n for n in NEVER_IN_RUNNER if n in runner})
        for line in (f'[runner] BT finished {self.finished}; exit {self.code}; '
                     f'timed out {self.timed_out}',
                     f'[runner] moves {self.moves}; validated with collision checking '
                     f'{self.validated}',
                     f'[runner] events {self.events}',
                     f'[runner] end-effector steps {self.steps}',
                     f'[move_group] {self.goals}',
                     f'[logs] lines that must never appear: {self.never or "none"}',
                     f'[shutdown] {self.stops}',
                     f'[hygiene] launch_params files in the workspace TMPDIR: '
                     f'{self.launch_params}'):
            self.say(line)


@pytest.fixture(scope='module')
def sample(tmp_path_factory):
    CL = _cl()
    if not os.environ.get('COLCON_PREFIX_PATH'):
        pytest.skip('needs a sourced workspace (ROS 2 Humble + the TrainIt workspace install)')
    import test_example_ur5e_suction as S      # one ur_description and xacro check for both
    S.needs_ur_description()
    from trainit_setup_assistant.generator import Orchestrator
    from trainit_setup_assistant.model import BundleSpec, load_project
    tmp = tmp_path_factory.mktemp('sample_ws')
    try:
        ws = CL._outside_the_underlay(tmp)
        with pytest.MonkeyPatch.context() as mp:
            mp.chdir(EXAMPLE)                # the README's rule: relative paths, from here
            project = load_project('project.yaml')
            project.bundle = BundleSpec.from_prefix(PREFIX)
            manifest = Orchestrator().generate(project, ws / 'src' / PREFIX)
        for package, floor in sorted(_floors(ws / 'src' / PREFIX / f'{PREFIX}_app' /
                                             'package.xml').items()):
            have = CL.installed_version(package)
            if have < floor:
                pytest.skip(f'{package} {CL._v(have)} is installed; the sample bundle declares '
                            f'>= {CL._v(floor)}')
        # what the bundle declares, or the probe imports, and this machine lacks:
        # named here, in seconds, instead of failing after minutes of building
        import launch_prereqs
        launch_prereqs.require(ws / 'src', modules=CL.PROBE_MODULES)
        try:
            summary = CL.build(ws)
        except Exception:
            # the temp workspace goes below, and CL.build keeps only colcon's last lines
            if os.environ.get(EVIDENCE) and (ws / 'log').is_dir():
                shutil.copytree(ws / 'log', Path(os.environ[EVIDENCE]) / 'ur5e_suction' /
                                'colcon_log', symlinks=True, dirs_exist_ok=True)
            raise
        run = SampleLaunch(ws)
        try:
            run.run()
        finally:
            if os.environ.get(EVIDENCE):
                run.save(Path(os.environ[EVIDENCE]) / 'ur5e_suction')
        yield dict(manifest=manifest, summary=summary, run=run)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def _why(sample) -> str:
    return '\n' + sample['run'].report()


def test_the_sample_generates_and_builds(sample):
    assert sample['manifest'].warnings == []
    assert '3 packages finished' in sample['summary'], sample['summary']


def test_the_bring_up_comes_up_on_mock(sample):
    run = sample['run']
    assert run.ready and all(run.ready.values()), _why(sample)


def test_the_tree_ends_success_within_the_timeout(sample):
    run = sample['run']
    assert (run.timed_out, run.finished, run.code) == (False, 'SUCCESS', 0), _why(sample)


def test_every_move_runs_in_order_and_is_validated_with_collision_checking(sample):
    run = sample['run']
    assert run.moves == SEQUENCE, _why(sample)
    assert run.validated == len(SEQUENCE), _why(sample)


def test_the_cup_engages_after_pick_and_releases_after_place(sample):
    run = sample['run']
    assert run.events == EXPECTED, _why(sample)
    assert run.steps == [('CloseGripper', SITE, 'SUCCESS', None),
                         ('OpenGripper', SITE, 'SUCCESS', None)], _why(sample)


def test_move_group_plans_and_executes_every_move(sample):
    assert sample['run'].goals == {what: len(SEQUENCE) for what, _p in GOALS}, _why(sample)


def test_no_log_names_a_missing_joint_a_failed_motion_or_a_contact(sample):
    assert sample['run'].never == [], _why(sample)


def test_every_launch_ends_cleanly_and_the_domain_is_empty_before_and_after(sample):
    run = sample['run']
    assert run.guards == {'before': [], 'after': []}, _why(sample)
    assert run.stops == {'runner': 'clean', 'bring-up': 'clean'}, _why(sample)
    assert run.launch_params > 0, _why(sample)     # launch_ros wrote into the workspace TMPDIR
